import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams } from 'react-router-dom';
import styled from 'styled-components';

// Styled Components
const Container = styled.div`
  font-family: 'Arial', sans-serif;
  background-color: #f4f4f9;
  padding: 20px;
`;

const Header = styled.div`
  background-color: #2c3e50;
  color: #fff;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 15px;
  border-radius: 8px;
  margin-bottom: 20px;
`;

const HeaderLeft = styled.div`
  font-size: 18px;
  font-weight: bold;
`;

const HeaderCenter = styled.div`
  font-size: 20px;
  font-weight: 600;
`;

const HeaderRight = styled.div`
  font-size: 16px;
`;

const DashboardOptions = styled.div`
  display: flex;
  gap: 20px;
  margin-top: 20px;
`;

const OptionButton = styled.button`
  background-color: #3498db;
  color: white;
  font-size: 16px;
  padding: 10px 20px;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  transition: background-color 0.3s;

  &:hover {
    background-color: #2980b9;
  }
`;

const SectionContainer = styled.div`
  margin-top: 30px;
`;

const SectionTitle = styled.h3`
  font-size: 22px;
  color: #333;
  margin-bottom: 15px;
`;

const Table = styled.table`
  width: 100%;
  border-collapse: collapse;
  margin-top: 15px;
`;

const TableHeader = styled.th`
  background-color: #3498db;
  color: white;
  padding: 10px;
  text-align: left;
`;

const TableData = styled.td`
  padding: 10px;
  text-align: left;
  border-bottom: 1px solid #ddd;
`;

const DashboardPage = () => {
  const { lorryId } = useParams();
  const [lorryDetails, setLorryDetails] = useState(null);
  const [selectedSection, setSelectedSection] = useState('employee');
  const [employeeData, setEmployeeData] = useState([]);
  const [fuelData, setFuelData] = useState([]);
  const [pointData, setPointData] = useState([]);

  useEffect(() => {
    // Fetch lorry details
    axios.get(`/api/lorry/${lorryId}`)
      .then(response => setLorryDetails(response.data))
      .catch(err => console.error(err));

    // Fetch employee, fuel, and point data
    axios.get(`/api/employees/${lorryId}`)
      .then(response => setEmployeeData(response.data))
      .catch(err => console.error(err));

    axios.get(`/api/fuel/${lorryId}`)
      .then(response => setFuelData(response.data))
      .catch(err => console.error(err));

    axios.get(`/api/points/${lorryId}`)
      .then(response => setPointData(response.data))
      .catch(err => console.error(err));
  }, [lorryId]);

  return (
    <Container>
      {lorryDetails && (
        <>
          <Header>
            <HeaderLeft>Reg. No: {lorryDetails.registration_number}</HeaderLeft>
            <HeaderCenter>{lorryDetails.owner_name}</HeaderCenter>
            <HeaderRight>Phone: {lorryDetails.owner_phone}</HeaderRight>
          </Header>

          <DashboardOptions>
            <OptionButton onClick={() => setSelectedSection('employee')}>Employee</OptionButton>
            <OptionButton onClick={() => setSelectedSection('fuel')}>Fuel Details</OptionButton>
            <OptionButton onClick={() => setSelectedSection('point')}>Point Details</OptionButton>
          </DashboardOptions>

          <SectionContainer>
            {selectedSection === 'employee' && (
              <>
                <SectionTitle>Employee Details</SectionTitle>
                <Table>
                  <thead>
                    <tr>
                      <TableHeader>Name</TableHeader>
                      <TableHeader>Role</TableHeader>
                      <TableHeader>Salary</TableHeader>
                      <TableHeader>Days Worked</TableHeader>
                    </tr>
                  </thead>
                  <tbody>
                    {employeeData.map((employee) => (
                      <tr key={employee.id}>
                        <TableData>{employee.name}</TableData>
                        <TableData>{employee.role}</TableData>
                        <TableData>{employee.salary}</TableData>
                        <TableData>{employee.daysWorked}</TableData>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              </>
            )}

            {selectedSection === 'fuel' && (
              <>
                <SectionTitle>Fuel Details</SectionTitle>
                <Table>
                  <thead>
                    <tr>
                      <TableHeader>Date</TableHeader>
                      <TableHeader>Bunk Name</TableHeader>
                      <TableHeader>Amount Paid</TableHeader>
                      <TableHeader>Remaining</TableHeader>
                    </tr>
                  </thead>
                  <tbody>
                    {fuelData.map((fuel) => (
                      <tr key={fuel.id}>
                        <TableData>{fuel.date}</TableData>
                        <TableData>{fuel.bunkName}</TableData>
                        <TableData>{fuel.amountPaid}</TableData>
                        <TableData>{fuel.remaining}</TableData>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              </>
            )}

            {selectedSection === 'point' && (
              <>
                <SectionTitle>Point Details</SectionTitle>
                <Table>
                  <thead>
                    <tr>
                      <TableHeader>Date</TableHeader>
                      <TableHeader>Agent Name</TableHeader>
                      <TableHeader>Amount Received</TableHeader>
                      <TableHeader>Remaining</TableHeader>
                    </tr>
                  </thead>
                  <tbody>
                    {pointData.map((point) => (
                      <tr key={point.id}>
                        <TableData>{point.date}</TableData>
                        <TableData>{point.agentName}</TableData>
                        <TableData>{point.amountReceived}</TableData>
                        <TableData>{point.remaining}</TableData>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              </>
            )}
          </SectionContainer>
        </>
      )}
    </Container>
  );
};

export default DashboardPage;
